    @Test public void selectionSurvivesDragInUnselectedTextWhileViewportScrolls(){
        InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{
            SelectionScrollView scroll=new SelectionScrollView(context());final boolean[] manualGesture={false};scroll.onUserGesture(()->manualGesture[0]=true);NotesController.WritingField field=new NotesController.WritingField(context());field.setTextSize(18);StringBuilder value=new StringBuilder();for(int i=0;i<200;i++)value.append("Line ").append(i).append(" selectable text\n");field.setText(value);scroll.addView(field,new android.widget.ScrollView.LayoutParams(-1,-2));scroll.measure(android.view.View.MeasureSpec.makeMeasureSpec(400,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(240,1073741824));scroll.layout(0,0,400,240);assertTrue(field.requestFocus());field.setSelection(1,7);
            long now=android.os.SystemClock.uptimeMillis();int[] actions={0,2,2,1};float[] y={210,160,90,80};for(int i=0;i<actions.length;i++){android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now+i*80,actions[i],360,y[i],0);try{assertTrue(scroll.dispatchTouchEvent(event));}finally{event.recycle();}}
            assertTrue("Deferred range drag still cancels automatic caret reveal",manualGesture[0]);assertEquals(1,field.getSelectionStart());assertEquals(7,field.getSelectionEnd());assertTrue("Actual ScrollView must move, not just swallow touch",scroll.getScrollY()>50);int position=scroll.getScrollY();assertTrue(scroll.manualRangeActive(field));assertFalse("Automatic native caret rectangle cannot override manual reading",scroll.requestChildRectangleOnScreen(field,new android.graphics.Rect(0,0,100,20),true));assertEquals(position,scroll.getScrollY());scroll.requestLayout();scroll.measure(android.view.View.MeasureSpec.makeMeasureSpec(400,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(240,1073741824));scroll.layout(0,0,400,240);assertEquals("Native ScrollView relayout retains the reading position",position,scroll.getScrollY());field.setSelection(1,8);assertFalse("A real endpoint change releases the manual viewport",scroll.manualRangeActive(field));
        });
    }
    @Test public void eighteenMiBThousandPagePdfOpensAndRendersLastPage()throws Exception{
        File file=File.createTempFile("public-large-pdf-",".pdf",context().getCacheDir());LocalPdfPreview.Document doc=null;
        try{com.tom_roush.pdfbox.android.PDFBoxResourceLoader.init(context());try(com.tom_roush.pdfbox.pdmodel.PDDocument generated=new com.tom_roush.pdfbox.pdmodel.PDDocument()){
            for(int i=0;i<1097;i++)generated.addPage(new com.tom_roush.pdfbox.pdmodel.PDPage());
            // Uncompressed synthetic attachment exercises real >18MiB I/O without private source pixels.
            com.tom_roush.pdfbox.pdmodel.common.PDStream padding=new com.tom_roush.pdfbox.pdmodel.common.PDStream(generated);try(OutputStream out=padding.createOutputStream()){byte[] block=new byte[8192];for(int i=0;i<2304;i++)out.write(block);}generated.getDocumentCatalog().getCOSObject().setItem("PublicFixturePadding",padding);generated.save(file);
        }assertTrue(file.length()>18L*1024*1024);long started=android.os.SystemClock.elapsedRealtime();doc=new LocalPdfPreview.Document(file);assertEquals(1097,doc.ratios.length);try(android.graphics.pdf.PdfRenderer.Page page=doc.renderer.openPage(1096)){android.graphics.Bitmap raster=android.graphics.Bitmap.createBitmap(120,170,android.graphics.Bitmap.Config.ARGB_8888);try{page.render(raster,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}finally{raster.recycle();}}
        android.util.Log.i("NotesPublicBenchmark","large_pdf_open_ms="+(android.os.SystemClock.elapsedRealtime()-started)+" bytes="+file.length()+" pages=1097");
        }finally{if(doc!=null){doc.closeText();doc.close();}file.delete();}
    }
    @Test public void wholeFileZoomPropagatesAndEachPageRemainsIndependent()throws Exception{
        File file=File.createTempFile("scope-zoom-",".pdf",context().getCacheDir());LocalPdfPreview.Document document=null;
        try{android.graphics.pdf.PdfDocument generated=new android.graphics.pdf.PdfDocument();try{for(int i=0;i<2;i++){android.graphics.pdf.PdfDocument.Page page=generated.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(600,800,i+1).create());generated.finishPage(page);}try(OutputStream out=new FileOutputStream(file)){generated.writeTo(out);}}finally{generated.close();}document=new LocalPdfPreview.Document(file);final LocalPdfPreview.Document owned=document;
            InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{LocalPdfPreview preview=new LocalPdfPreview(context(),new NotesDesign(context(),false),owned);preview.measure(android.view.View.MeasureSpec.makeMeasureSpec(400,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(1600,1073741824));preview.layout(0,0,400,1600);androidx.recyclerview.widget.RecyclerView pages;try{java.lang.reflect.Field field=LocalPdfPreview.class.getDeclaredField("pages");field.setAccessible(true);pages=(androidx.recyclerview.widget.RecyclerView)field.get(preview);}catch(Exception error){throw new AssertionError(error);}assertNotNull(pages);assertTrue("Both real page holders must be laid out",pages.getChildCount()>=2);ZoomablePageImage first=(ZoomablePageImage)pages.getChildAt(0),second=(ZoomablePageImage)pages.getChildAt(1);
                preview.setZoomScope(false);first.restoreZoom(new float[]{2,.5f,.5f,0,0});first.zoomChanged.accept(first.savedZoom());assertEquals(1,second.zoomFactor(),.001f);
                preview.setZoomScope(true);assertEquals(2,preview.savedViewport().getFloat("fileScale"),.001f);assertEquals("Whole-file zoom resizes pages, never crops the page image",1,second.zoomFactor(),.001f);assertEquals(800,pages.getLayoutParams().width);first.fileScaleChanged.accept(1.5f);assertEquals(3,preview.savedViewport().getFloat("fileScale"),.001f);assertEquals(1200,pages.getLayoutParams().width);
                preview.setZoomScope(false);first.restoreZoom(new float[]{1.5f,.5f,.5f,0,0});first.zoomChanged.accept(first.savedZoom());assertEquals(1,second.zoomFactor(),.001f);assertEquals(400,pages.getLayoutParams().width);assertFalse(preview.savedViewport().getBoolean("fileZoom"));preview.close();
            });document=null;
        }finally{if(document!=null){document.closeText();document.close();}file.delete();}
    }
